practiceBank.starter:
const raw = require("fs").readFileSync(0, "utf8");
let [a, b] = raw.trim().split(/\s+/).map(Number);
// Напиши решение

practiceBank.solution:
const raw = require("fs").readFileSync(0, "utf8");
let [a, b] = raw.trim().split(/\s+/).map(Number);
while (b != 0) { let r = a % b; a = b; b = r; } let answer = a;
console.log(answer);

practiceBank.starter:
const raw = require("fs").readFileSync(0, "utf8");
let n = Number(raw.trim());
// Напиши решение

practiceBank.solution:
const raw = require("fs").readFileSync(0, "utf8");
let n = Number(raw.trim());
let answer = 0; for (let i = 1; i <= n; i++) if (i % 3 == 0) answer += i;
console.log(answer);

