const fs = require("node:fs");
const values = fs.readFileSync(0, "utf8").trim().split(/\s+/).map(Number);
const [n, k] = values;
const a = values.slice(2);

let dp = Array(k + 1).fill(1000000);
dp[0] = 0;
for (let amount = 1; amount <= k; amount++) {
    for (let i = 0; i < n; i++) {
        if (a[i] <= amount) {
            dp[amount] = Math.min(dp[amount], dp[amount - a[i]] + 1);
        }
    }
}
let answer = dp[k];
if (answer >= 1000000) {
    answer = -1;
}
console.log(answer);

