sections.code:
const fs = require("node:fs");
const values = fs.readFileSync(0, "utf8").trim().split(/\s+/).map(Number);
const [n, k] = values;
const a = values.slice(2);

let distance = Array(n).fill(1000000000);
let used = Array(n).fill(0);
distance[k] = 0;
for (let step = 0; step < n; step++) {
    let vertex = -1;
    for (let i = 0; i < n; i++) {
        if (used[i] === 0) {
            if (vertex === -1 || distance[i] < distance[vertex]) {
                vertex = i;
            }
        }
    }
    if (vertex === -1 || distance[vertex] === 1000000000) {
        break;
    }
    used[vertex] = 1;
    for (let next = 0; next < n; next++) {
        let weight = a[vertex * n + next];
        if (weight >= 0 && used[next] === 0) {
            distance[next] = Math.min(distance[next], distance[vertex] + weight);
        }
    }
}
for (let i = 0; i < n; i++) {
    let value = distance[i];
    if (value === 1000000000) {
        value = -1;
    }
    console.log(value);
}

